"spring": `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200" role="img" aria-labelledby="il-spring-t" font-family="system-ui,sans-serif" font-size="11" fill="#1e293b"><title id="il-spring-t">彈簧與虎克定律</title><defs><marker id="spring-m0" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#dc2626"/></marker><marker id="spring-m1" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#334155"/></marker></defs><rect x="8" y="26" width="8" height="48" fill="#94a3b8" stroke="#334155"/><rect x="8" y="98" width="8" height="48" fill="#94a3b8" stroke="#334155"/><path d="M16 50L18.1 42L22.3 58L26.5 42L30.7 58L34.9 42L39.1 58L43.3 42L47.5 58L51.7 42L55.9 58L60.1 42L64.3 58L68.5 42L72.7 58L76.9 42L81.1 58L85.3 42L89.5 58L93.7 42L97.9 58L100 50" stroke="#334155" stroke-width="1.5" fill="none"/><rect x="100" y="36" width="30" height="28" rx="3" fill="#93c5fd" stroke="#334155" stroke-width="1.5"/><path d="M16 122L19.1 114L25.3 130L31.5 114L37.7 130L43.9 114L50.1 130L56.3 114L62.5 130L68.7 114L74.9 130L81.1 114L87.3 130L93.5 114L99.7 130L105.9 114L112.1 130L118.3 114L124.5 130L130.7 114L136.9 130L140 122" stroke="#334155" stroke-width="1.5" fill="none"/><rect x="140" y="108" width="30" height="28" rx="3" fill="#93c5fd" stroke="#334155" stroke-width="1.5"/><path d="M100 28V84M100 104V150" stroke="#64748b" stroke-dasharray="3 3"/><text x="22" y="20" font-size="10" fill="#475569">自然長度 natural length</text><text x="96" y="160" text-anchor="end" font-size="10" fill="#475569">x = 0</text><path d="M100 146H140M140 141v10" stroke="#b45309" stroke-width="1.5"/><text x="124" y="160" text-anchor="middle" font-size="11" fill="#b45309" font-weight="700">x</text><path d="M170 96L128 96" stroke="#dc2626" stroke-width="2.5" fill="none" marker-end="url(#spring-m0)"/><text x="124" y="92" text-anchor="end" font-size="11" fill="#dc2626" font-weight="700">回復力 F = −kx</text><text x="8" y="180" font-size="10" fill="#475569">k：力常數 spring constant (N/m)</text><text x="8" y="194" font-size="10" fill="#475569">F 與伸長量 x 方向相反</text><path d="M215 160L275 160L275 85Z" fill="#fde68a" stroke="#f59e0b"/><path d="M215 166L215 30" stroke="#334155" stroke-width="1.5" fill="none" marker-end="url(#spring-m1)"/><path d="M209 160L308 160" stroke="#334155" stroke-width="1.5" fill="none" marker-end="url(#spring-m1)"/><path d="M215 160L295 60" stroke="#dc2626" stroke-width="2.5"/><text x="220" y="30" font-size="10" font-weight="700">|F| (N)</text><text x="306" y="152" text-anchor="end" font-size="11" font-weight="700">x</text><text x="230" y="92" font-size="10" fill="#dc2626" font-weight="700">斜率 k</text><text x="240" y="152" font-size="10" font-weight="700">U=½kx²</text><text x="258" y="176" text-anchor="middle" font-size="10" fill="#b45309">面積 = 彈性位能</text><text x="258" y="190" text-anchor="middle" font-size="10" fill="#475569">elastic PE</text></svg>`,

"work-energy": `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200" role="img" aria-labelledby="il-work-energy-t" font-family="system-ui,sans-serif" font-size="11" fill="#1e293b"><title id="il-work-energy-t">功與功能定理</title><defs><marker id="work-energy-m0" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#9333ea"/></marker><marker id="work-energy-m1" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#16a34a"/></marker></defs><text x="8" y="16" font-size="12" font-weight="700">功 work = 力 × 位移（沿力方向）</text><path d="M10 120H310" stroke="#334155" stroke-width="2"/><rect x="30" y="90" width="40" height="30" rx="3" fill="#93c5fd" stroke="#334155" stroke-width="1.5"/><rect x="210" y="90" width="40" height="30" rx="3" fill="#93c5fd" fill-opacity=".4" stroke="#334155" stroke-dasharray="4 3"/><path d="M50 105H102" stroke="#9333ea" stroke-dasharray="3 2"/><path d="M50 105L102 75" stroke="#9333ea" stroke-width="3" fill="none" marker-end="url(#work-energy-m0)"/><text x="106" y="74" font-size="13" fill="#9333ea" font-weight="700">F</text><path d="M80 105A30 30 0 0 0 76 90" stroke="#334155" fill="none"/><text x="84" y="100" font-size="11" font-weight="700">θ</text><path d="M50 136H230M50 131v10M230 131v10" stroke="#b45309" stroke-width="1.5"/><text x="140" y="150" text-anchor="middle" font-size="11" fill="#b45309" font-weight="700">位移 d</text><path d="M40 164L62 164" stroke="#16a34a" stroke-width="2" fill="none" marker-end="url(#work-energy-m1)"/><text x="66" y="168" font-size="11" fill="#16a34a" font-weight="700">v₁</text><path d="M210 164L252 164" stroke="#16a34a" stroke-width="2" fill="none" marker-end="url(#work-energy-m1)"/><text x="256" y="168" font-size="11" fill="#16a34a" font-weight="700">v₂</text><text x="160" y="186" text-anchor="middle" font-size="11" font-weight="700">W = F d cos θ = ΔK = ½mv₂² − ½mv₁²</text><text x="304" y="40" text-anchor="end" font-size="11" fill="#dc2626" font-weight="700">功能定理</text><text x="304" y="53" text-anchor="end" font-size="10" fill="#475569">work–energy theorem</text></svg>`,

